import{_ as d,o as t,c as o,a2 as a}from"./chunks/framework.brrhTSPk.js";const p=JSON.parse('{"title":"Referência de API","description":"","frontmatter":{},"headers":[],"relativePath":"pt/guide/api-reference.md","filePath":"pt/guide/api-reference.md","lastUpdated":1788227913000}'),c={name:"pt/guide/api-reference.md"};function r(n,e,i,s,l,m){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="referencia-de-api" tabindex="-1">Referência de API <a class="header-anchor" href="#referencia-de-api" aria-label="Permalink to &quot;Referência de API&quot;">​</a></h1><p>Assinaturas completas de cada tipo público, atualizadas para a <strong>0.4.0</strong>. Para prosa e exemplos, siga os guias por módulo; esta página é a consulta rápida.</p><h2 id="option-lt-t-gt" tabindex="-1">Option&lt;T&gt; <a class="header-anchor" href="#option-lt-t-gt" aria-label="Permalink to &quot;Option&amp;lt;T&amp;gt;&quot;">​</a></h2><p><code>Maybe\\Option\\Option</code> — um valor opcional, <code>Some</code> ou <code>None</code>.</p><table tabindex="0"><thead><tr><th>Membro</th><th>Assinatura</th><th>Descrição</th></tr></thead><tbody><tr><td><code>Option::some</code></td><td><code>some($value): Option&lt;T&gt;</code></td><td>Envolve um valor presente (nunca <code>null</code>).</td></tr><tr><td><code>Option::none</code></td><td><code>none(): Option&lt;mixed&gt;</code></td><td>O option vazio.</td></tr><tr><td><code>Option::fromNullable</code></td><td><code>fromNullable($value): Option&lt;T&gt;</code></td><td><code>null</code> → <code>None</code>, senão <code>Some</code>.</td></tr><tr><td><code>map</code></td><td><code>map(callable $fn): Option</code></td><td>Transforma o valor; resultado <code>null</code> colapsa para <code>None</code>.</td></tr><tr><td><code>flatMap</code></td><td><code>flatMap(callable $fn): Option</code></td><td>Encadeia operação que retorna <code>Option</code>.</td></tr><tr><td><code>filter</code></td><td><code>filter(callable $predicate): Option</code></td><td>Mantém o valor só se o predicado for verdadeiro.</td></tr><tr><td><code>match</code></td><td><code>match(callable $onSome, callable $onNone)</code></td><td>Trata os dois ramos, retorna o resultado.</td></tr><tr><td><code>unwrap</code></td><td><code>unwrap()</code></td><td>O valor, ou lança <code>UnwrapNoneException</code> em <code>None</code>.</td></tr><tr><td><code>unwrapOr</code></td><td><code>unwrapOr($default)</code></td><td>O valor, ou fallback imediato.</td></tr><tr><td><code>unwrapOrElse</code></td><td><code>unwrapOrElse(callable $fn)</code></td><td>O valor, ou fallback lazy.</td></tr><tr><td><code>expect</code></td><td><code>expect(string $message)</code></td><td>O valor, ou lança com sua mensagem.</td></tr><tr><td><code>okOr</code></td><td><code>okOr($error): Result</code></td><td><code>Some</code>→<code>Ok</code>, <code>None</code>→<code>Err($error)</code>.</td></tr><tr><td><code>okOrElse</code></td><td><code>okOrElse(callable $fn): Result</code></td><td>Como <code>okOr</code>, erro calculado lazy.</td></tr><tr><td><code>isSome</code> / <code>isNone</code></td><td><code>(): bool</code></td><td>Inspeciona a variante.</td></tr></tbody></table><h2 id="result-lt-t-e-gt" tabindex="-1">Result&lt;T, E&gt; <a class="header-anchor" href="#result-lt-t-e-gt" aria-label="Permalink to &quot;Result&amp;lt;T, E&amp;gt;&quot;">​</a></h2><p><code>Maybe\\Result\\Result</code> — um sucesso (<code>Ok</code>) ou uma falha tipada (<code>Err</code>).</p><table tabindex="0"><thead><tr><th>Membro</th><th>Assinatura</th><th>Descrição</th></tr></thead><tbody><tr><td><code>Result::ok</code></td><td><code>ok($value): Result&lt;T,mixed&gt;</code></td><td>Um sucesso.</td></tr><tr><td><code>Result::err</code></td><td><code>err($error): Result&lt;mixed,E&gt;</code></td><td>Uma falha tipada.</td></tr><tr><td><code>map</code></td><td><code>map(callable $fn): Result</code></td><td>Transforma o valor de sucesso.</td></tr><tr><td><code>mapErr</code></td><td><code>mapErr(callable $fn): Result</code></td><td>Transforma o valor de erro.</td></tr><tr><td><code>andThen</code></td><td><code>andThen(callable $fn): Result</code></td><td>Encadeia op falível; curto-circuita em <code>Err</code>.</td></tr><tr><td><code>orElse</code></td><td><code>orElse(callable $fn): Result</code></td><td>Recupera de <code>Err</code>; passa <code>Ok</code> adiante.</td></tr><tr><td><code>match</code></td><td><code>match(callable $onOk, callable $onErr)</code></td><td>Trata os dois ramos.</td></tr><tr><td><code>unwrap</code></td><td><code>unwrap()</code></td><td>O valor, ou lança <code>UnwrapErrException</code> em <code>Err</code>.</td></tr><tr><td><code>unwrapErr</code></td><td><code>unwrapErr()</code></td><td>O erro, ou lança <code>UnwrapOkException</code> em <code>Ok</code>.</td></tr><tr><td><code>unwrapOr</code></td><td><code>unwrapOr($default)</code></td><td>O valor, ou fallback imediato.</td></tr><tr><td><code>unwrapOrElse</code></td><td><code>unwrapOrElse(callable $fn)</code></td><td>O valor, ou fallback calculado do erro.</td></tr><tr><td><code>expect</code></td><td><code>expect(string $message)</code></td><td>O valor, ou lança com sua mensagem.</td></tr><tr><td><code>okOption</code></td><td><code>okOption(): Option</code></td><td><code>Ok(v)</code>→<code>Some(v)</code>, <code>Err</code>→<code>None</code>.</td></tr><tr><td><code>errOption</code></td><td><code>errOption(): Option</code></td><td><code>Err(e)</code>→<code>Some(e)</code>, <code>Ok</code>→<code>None</code>.</td></tr><tr><td><code>isOk</code> / <code>isErr</code></td><td><code>(): bool</code></td><td>Inspeciona a variante.</td></tr></tbody></table><h2 id="schema" tabindex="-1">Schema <a class="header-anchor" href="#schema" aria-label="Permalink to &quot;Schema&quot;">​</a></h2><p><code>Maybe\\Schema\\Schema</code> — builders de validadores imutáveis. Todo modificador retorna uma nova instância.</p><table tabindex="0"><thead><tr><th>Builder</th><th>Assinatura</th></tr></thead><tbody><tr><td><code>Schema::string</code></td><td><code>string(): StringSchema</code></td></tr><tr><td><code>Schema::int</code></td><td><code>int(): IntSchema</code></td></tr><tr><td><code>Schema::bool</code></td><td><code>bool(): BoolSchema</code></td></tr><tr><td><code>Schema::date</code></td><td><code>date(): DateSchema</code></td></tr><tr><td><code>Schema::enumeration</code></td><td><code>enumeration(array $allowedValues): EnumSchema</code></td></tr><tr><td><code>Schema::arrayOf</code></td><td><code>arrayOf(SchemaInterface $itemSchema): ArraySchema</code></td></tr><tr><td><code>Schema::shape</code></td><td><code>shape(array $shape): ObjectSchema</code></td></tr><tr><td><code>Schema::option</code></td><td><code>option(SchemaInterface $inner): OptionSchema</code></td></tr></tbody></table><p><strong>Modificadores:</strong> <code>StringSchema</code>: <code>-&gt;trimmed()</code>, <code>-&gt;min(int)</code>, <code>-&gt;max(int)</code>, <code>-&gt;regex(string)</code>. <code>IntSchema</code>: <code>-&gt;min(int)</code>, <code>-&gt;max(int)</code>. <code>DateSchema</code>: <code>-&gt;format(string)</code>, <code>-&gt;min(DateTimeImmutable)</code>, <code>-&gt;max(DateTimeImmutable)</code>. <code>ObjectSchema</code>: <code>-&gt;allowUnknown()</code>.</p><p><strong>Pontos de entrada (todos os schemas):</strong> <code>-&gt;safeParse($input): Result&lt;T, ValidationErrorBag&gt;</code> (nunca lança) e <code>-&gt;parse($input): T</code> (lança <code>ValidationException</code>). <code>-&gt;transform(callable): SchemaInterface</code>.</p><h2 id="erros-de-validacao-0-4-0" tabindex="-1">Erros de validação (0.4.0) <a class="header-anchor" href="#erros-de-validacao-0-4-0" aria-label="Permalink to &quot;Erros de validação (0.4.0)&quot;">​</a></h2><p>Value objects Tell-Don&#39;t-Ask — <strong>não</strong> existem getters <code>path()</code>, <code>message()</code>, <code>code()</code>, <code>all()</code> ou <code>first()</code>.</p><p><code>Maybe\\Schema\\ValidationErrorBag</code> — coleção de primeira classe, <code>Countable</code> e iterável.</p><table tabindex="0"><thead><tr><th>Membro</th><th>Assinatura</th><th>Descrição</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>count(): int</code></td><td>Número de erros (<code>Countable</code>).</td></tr><tr><td><code>isEmpty</code></td><td><code>isEmpty(): bool</code></td><td>Se não há erros.</td></tr><tr><td>iteração</td><td><code>foreach ($bag as $error)</code></td><td>Entrega itens <code>ValidationError</code>.</td></tr><tr><td><code>describe</code></td><td><code>describe(): string[]</code></td><td>Uma linha <code>&quot;path: message&quot;</code> por erro.</td></tr><tr><td><code>summary</code></td><td><code>summary(): string</code></td><td>Primeira linha mais &quot;(and N more…)&quot;.</td></tr><tr><td><code>toArray</code></td><td><code>toArray(): array[]</code></td><td>Fronteira de serialização: linhas <code>[&#39;path&#39;,&#39;message&#39;,&#39;code&#39;]</code>.</td></tr><tr><td><code>withError</code> / <code>merge</code></td><td><code>(...): self</code></td><td>Adição / combinação imutável.</td></tr></tbody></table><p><code>Maybe\\Schema\\ValidationError</code>: <code>describedAs(): string</code>, <code>underField(string): self</code>, <code>underIndex(int): self</code>, <code>toArray(): array{path,message,code}</code>. Crie um com um <code>Path</code>: <code>new ValidationError(Path::field(&#39;email&#39;), &#39;message&#39;, &#39;code&#39;)</code>.</p><p><code>Maybe\\Schema\\Path</code>: <code>Path::root(): self</code>, <code>Path::field(string): self</code>, <code>-&gt;underField(string): self</code>, <code>-&gt;underIndex(int): self</code>, <code>-&gt;toString(): string</code>.</p><h2 id="dto" tabindex="-1">DTO <a class="header-anchor" href="#dto" aria-label="Permalink to &quot;DTO&quot;">​</a></h2><p><code>Maybe\\DTO\\DTO</code> — base abstrata que mapeia input validado em um objeto tipado.</p><table tabindex="0"><thead><tr><th>Membro</th><th>Assinatura</th><th>Descrição</th></tr></thead><tbody><tr><td><code>schema</code></td><td><code>abstract static schema(): ObjectSchema</code></td><td>Define a forma.</td></tr><tr><td><code>fromValidated</code></td><td><code>abstract static protected fromValidated(array): static</code></td><td>Constrói a instância a partir dos dados validados.</td></tr><tr><td><code>fromArray</code></td><td><code>static fromArray(array $input): Result&lt;static, ValidationErrorBag&gt;</code></td><td>Valida, nunca lança.</td></tr><tr><td><code>parse</code></td><td><code>static parse(array $input): static</code></td><td>Valida, lança em input inválido.</td></tr></tbody></table><h2 id="async" tabindex="-1">Async <a class="header-anchor" href="#async" aria-label="Permalink to &quot;Async&quot;">​</a></h2><p><code>Maybe\\Async\\Async</code> e <code>AsyncFuture</code> — concorrência via processos filhos (<code>proc_open</code>).</p><table tabindex="0"><thead><tr><th>Membro</th><th>Assinatura</th><th>Descrição</th></tr></thead><tbody><tr><td><code>async</code></td><td><code>async(callable $task, array $args = [], array $options = []): AsyncFuture</code></td><td>Inicia uma task. <code>options: [&#39;timeout&#39; =&gt; 2.5]</code>. Envolve <code>Async::run</code>.</td></tr><tr><td><code>await</code></td><td><code>await($futureOrArray)</code></td><td>Resolve um future, ou um array via <code>Async::all</code>.</td></tr><tr><td><code>Async::run</code></td><td><code>run(callable $task, array $args = [], array $options = []): AsyncFuture</code></td><td>Igual a <code>async()</code>, chamado direto na classe.</td></tr><tr><td><code>Async::all</code></td><td><code>all(array $futures): array</code></td><td>Espera todos (chaves preservadas).</td></tr><tr><td><code>Async::race</code></td><td><code>race(array $futures)</code></td><td>O primeiro a terminar vence.</td></tr><tr><td><code>Async::pool</code></td><td><code>pool(array $tasks, int $limit = 5, array $options = []): array</code></td><td>Concorrência limitada.</td></tr><tr><td><code>Async::setDefaultTempDir</code></td><td><code>setDefaultTempDir(string $tempDir): void</code></td><td>Sobrescreve onde os arquivos temporários do worker são escritos.</td></tr><tr><td><code>Async::setDefaultTimeout</code></td><td><code>setDefaultTimeout(?float $seconds): void</code></td><td>Timeout padrão por task quando <code>options[&#39;timeout&#39;]</code> é omitido.</td></tr><tr><td><code>Async::setDefaultPollInterval</code></td><td><code>setDefaultPollInterval(int $microseconds): void</code></td><td>Intervalo de polling padrão usado ao esperar um future.</td></tr><tr><td><code>Async::setDefaultMaxInputBytes</code></td><td><code>setDefaultMaxInputBytes(?int $bytes): void</code></td><td>Limite padrão de entrada serializada; <code>null</code> desativa.</td></tr><tr><td><code>Async::setDefaultMaxOutputBytes</code></td><td><code>setDefaultMaxOutputBytes(?int $bytes): void</code></td><td>Limite padrão de saída serializada; <code>null</code> desativa.</td></tr><tr><td><code>AsyncFuture</code></td><td><code>-&gt;then(fn)</code>, <code>-&gt;catch(fn)</code>, <code>-&gt;finally(fn)</code></td><td>Registra callbacks.</td></tr><tr><td></td><td><code>-&gt;resolve()</code></td><td>Bloqueia até terminar (ou timeout).</td></tr><tr><td></td><td><code>-&gt;pending(): bool</code>, <code>-&gt;cancel()</code></td><td>Checagem não bloqueante / mata o processo.</td></tr></tbody></table><p>As opções de tamanho da Async são <code>max_input_bytes</code> (16 MiB por padrão), <code>max_output_bytes</code> (64 MiB por padrão) e <code>include_remote_trace</code> (desativado por padrão). Um limite pode ser <code>null</code> para uma carga confiável e explicitamente limitada.</p><p><code>Maybe\\Async\\Exception\\PayloadTooLargeException</code> informa qual direção do IPC excedeu o limite. <code>TaskFailedException::remoteTrace()</code> fica vazio por padrão; ative <code>include_remote_trace</code> somente em diagnósticos confiáveis.</p><h2 id="funcoes-helper-globais" tabindex="-1">Funções helper globais <a class="header-anchor" href="#funcoes-helper-globais" aria-label="Permalink to &quot;Funções helper globais&quot;">​</a></h2><p>Auto-carregadas (namespace <code>Maybe\\</code>): <code>some()</code>, <code>none()</code>, <code>fromNullable()</code>, <code>ok()</code>, <code>err()</code>, <code>stringSchema()</code>, <code>intSchema()</code>, <code>boolSchema()</code>, <code>dateSchema()</code>, <code>enumSchema()</code>, <code>arraySchema()</code>, <code>objectSchema()</code>, <code>optionSchema()</code>, <code>async()</code>, <code>await()</code>.</p><blockquote><p>Escrevendo código com um assistente de IA? Aponte-o para o <a href="/maybe/llms.txt"><code>llms.txt</code></a> para as mesmas assinaturas em formato amigável a LLM.</p></blockquote>',30)])])}const h=d(c,[["render",r]]);export{p as __pageData,h as default};
